CREATE COLUMN TABLE "TEST_AP"."TRN2" ("TrnAbsEntr" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "SubLineNum" INTEGER CS_INT NOT NULL , "LangCode" INTEGER CS_INT NOT NULL , "Text" NCLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("TrnAbsEntr", "LineNum", "SubLineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "TRN2_UniqueIdx" ON "TEST_AP"."TRN2" ( "TrnAbsEntr" ASC, "LineNum" ASC, "LangCode" ASC )